\begin{enumerate}
        \item We will assume throughout that $f(0^+)<f(1^-)$ since in that case, $\mathcal{A}_1\implies\mathcal{A}_2$ (see \cite[Section 5]{JK1}).
        \item As in \cite{JK2}, Proposition \ref{prop:main} can be strengthened in the sense that one can show uniform localization, also leading to a so-called ``Area Law'', as discussed in \cite{PS}.
    \end{enumerate}

\label{lemma:ac_IDS}
    Under assumptions $\mathcal{A}_1$ and $\mathcal{A}_2$, $N(\cdot)$ is Lipschitz continuous and satisfies
    \begin{equation}
    |N(E_2)-N(E_1)|\leq\gamma^{-1}|E_2-E_1|
\end{equation}

Fix $\sigma\in(0,1)$. Given $n\in\mathbb{N}$ and $\mu>0$, an integer $m\in\mathbb{Z}$ will be called \textit{$(\mu,n)$-regular} if there exists an interval $[n_1,n_2]\subseteq\mathbb{Z}$, called the \textit{regularity interval}, such that $n_2-n_1+1=n$, and
    \begin{enumerate}
        \item $m\in[n_1,n_2]$.\label{item1}
        \item $\operatorname{dist}(m,\{n_1,n_2\})\geq\sigma n$.\label{item2}
        \item $|(H_{[n_1,n_2]}-E)^{-1}(n_i,m)|\leq e^{-\mu|n_i-m|}$ for $i=1,2$.
    \end{enumerate}
    If \ref{item1} and \ref{item2} hold and for some solution $\psi$ we have
    \begin{equation}\label{eq:psi_regular}
    |\psi(m)| \le e^{-\mu|m-n_1|}\,|\psi(n_1-1)| + e^{-\mu|m-n_2|}\,|\psi(n_2+1)|,
    \end{equation}
    then we will say that $m$ is $(\psi,\mu,n)$-regular and that $[n_1,n_2]$ is a $(\psi,\mu)$-regularity interval for $m$.

\label{lemma:Liouville_transition_resonant}
Let $\psi$ be a generalized eigenfunction at energy $E$ normalized to $|\psi(0)|^2+|\psi(1)|^2=1$. For sufficiently large $k$, if $q_{k+1}>q_k^C$, then
every resonant point $m\in R_j$ with $0< |j|\leq\frac{q_{k+1}}{10q_k}$ is $\left(\psi,\frac{\log|j|}{q_k}+L(E)-\beta_k-3\tau,r(1+O(\tau))\right)$-regular, where $\beta_k=\frac{\ln q_{k+1}}{q_k}$ and $r=2q_k$ or $r=4q_k$.

\label{proposition:hf_bound_warmup}
We partition $\mathbb{T}$ into the interval $\mathsf{A} = (0,1-\delta)$ and its complement $\mathsf{A}^c = [1-\delta,1]$. Assume that $\delta < \min(\lVert \alpha\rVert, \lVert 2\alpha\rVert)$. 

Let $f:\mathbb{T}\to \mathbb{R}$ be continuously differentiable on $(0,1)$. We define
$$\gamma_+ = \inf_{x\in\mathsf{A}} f'(x), \qquad \gamma_- = \inf_{x\in \mathsf{A}^c} f'(x),$$
and assume that $\gamma_+>0$ and $\gamma_-\leq 0$. Then any eigenvalue curve satisfies
\begin{equation}
\label{eq:hf_bound_warmup}
E_k'(x) \geq c_+ \gamma_+ + c_- \gamma_-
\end{equation}
with the constants
$$c_+ = \frac{1}{1+2(3+2\lVert f\rVert_\infty)^2}, \qquad c_- = 1-c_+ = \frac{2(3+2\lVert f\rVert_\infty)^2}{1+2(3+2\lVert f\rVert_\infty)^2}$$
and for any $x \in (0,1)$ not equal to one of the jump points $\beta_1,...,\beta_n$.

\label{prop:HF_formula}
Let $x\in I \mapsto h(x)\in M_n(\mathbb{C})$ be a continuous function mapping an interval to self-adjoint matrices with simple eigenvalues. For every $x$ there exists a neighborhood $U$ such that there exist $n$ orthonormal eigenvalue-eigenvector pairs $(E_k(y),\psi_k(y))$ for $y\in U$ such that $y\in U\mapsto E_k(y)$ and $y\in U\mapsto \psi_k(y)$ are continuous. If $h$ is differentiable at $x$ then in addition the functions $E_k$ are differentiable at $x$ and
\begin{equation}\label{eq:HF}
E'_k(x)=  \frac{\langle\psi_k(x), h'(x)\psi_k(x)\rangle}{\langle\psi_k(x),\psi_k(x)\rangle}
\end{equation}
If $h$ is absolutely continuous in the neighborhood $U$ then the same is true for the functions $E_k$ and
$$E_k(x)-E_k(y) = \int_{y}^{x} E'_k(z) dz$$
for all $x,y\in U$ with the almost everywhere defined derivatives.

\label{cor:HF_formula}
If $f\rvert_{(0,1)}$ is a piecewise absolutely continuous sampling function then for all $n$ all eigenvalue branches $E_k(x)$ of $H_n(x)$ are piecewise absolutely continuous.

		If $f\rvert_{(0,1)}$ is instead monotone and piecewise continuous then all eigenvalue branches $E_k(x)$ of $H_n(x)$ are monotone and piecewise continuous on each monotonicity interval.

		In both cases the eigenvalue curves $E_k$ are almost everywhere differentiable on each monotonicity interval. If $(E_k(x), \psi_k)$ is an eigenvalue-eigenvector pair of $H_n(x)$ with normalized $\|\psi_k\|=1$ and $f$ is differentiable at every sampled point $x+i\alpha$, $0\leq i<n$, then one has
\begin{equation}\label{eq:HF2}
E'_k(x)=\sum_{i=0}^{n-1} |\psi_k(i)|^2\,f'(x+i\alpha)
\end{equation}

\label{lemma:poisson_mass_transfer}
Consider the finite-volume Hamiltonian $H_n(x)$ on the integer interval $[0,n-1]$ with a bounded sampling function $f$ such that $\lVert f\rVert_\infty \leq C$ for some constant. Let $(E,\psi)$ be any eigenvalue-eigenvector pair of $H_n(x)$ for some $x\in \mathbb{T}$ with $\psi$ normalized. 

		Assume that there exists some set $\mathsf{A} \subset \mathbb{T}$, an open interval $I\subset \mathsf{A}$ and some positive integer $\ell$ such that $x+\ell\alpha \in \mathsf{A}$ for every $x\in I$ and, if $\ell>1$, that
\begin{equation}
\label{eq:E_not_eigenvalue}
\mathrm{dist}\left(E, \sigma\left(H_{[1,\ell-1]}(x)\right)\right)\geq \delta, \qquad \forall x\in I.
\end{equation}
 For $x\in \mathbb{T}$ denote then $\mathcal N_{\mathsf{A}}(x)=\{i \in \mathbb{Z}: \; x+i\alpha \in \mathsf{A}\}$.

		For fixed $C$ and $\alpha$ there then exists a constant $\eta_{\delta, I, \ell}>0$ depending on $\delta$, $I$, and $\ell$ such that 
\begin{equation}
\label{eq:mass_lowerbound1}
\sum_{i\in\mathcal N_{\mathsf{A}}(x)}|\psi(i)|^2 \ \ge\ \frac{\eta_{\delta,I, \ell}}{1+\eta_{\delta,I, \ell}}
\end{equation}
uniformly for all sufficiently large $n$.

\label{prop:mass_lower_bound}
Consider the finite-volume Hamiltonian $H_n(x)$ on the integer interval $[0,n-1]$ with a non-negative bounded piecewise-continuous sampling function $f$.

Let $\mathsf{A}\subset \mathbb{T}$ be a non-empty open interval. If all $x\in \mathsf{A}$ satisfy $\ell_\mathsf{A}(x)>1$ then let $\tilde{\mathsf{A}}$ be the set of continuity points of the map $$x \in \mathsf{A} \mapsto H_{[1,\ell_{\mathsf{A}}(x)-1]}(x)$$ and assume that there does not exist any $E\in {\mathbb R}$ which is simultaneously an eigenvalue of all of the matrices
$$\left(H_{[1,\ell_\mathsf{A}(x)-1]}(x)\right)_{x\in \tilde{\mathsf{A}}}.$$ Then there exists a constant $\eta>0$ such that for any normalized eigenvalue-eigenvector pair $(E,\psi)$ of $H_n(x)$ one has
\begin{equation}
\label{eq:mass_lowerbound}
\sum_{i\in\mathcal N_{\mathsf{A}}(x)}|\psi(i)|^2 \ \ge\ \frac{\eta}{1+\eta}
\end{equation}
uniformly in $x\in \mathbb{T}$ and for all sufficiently large $n$.

\label{lemma:common_eigenvector}
Let $I=[a,b]$ be an interval and $x\in I \mapsto H(x)= \Delta_\ell + V(x) \in M_\ell(\mathbb{C})$ a family of self-adjoint matrices with $\Delta_\ell$ the discrete Dirichlet-Laplacian on $[1,\ell]$ and $x\mapsto V(x)$ a continuous monotone family of diagonal matrices with $V(x) \leq V(y)$ for $x<y$. If there exists some $E\in \mathbb{R}$ which is an eigenvalue for all $H(x)$ then there exists a common eigenvector $\psi$ with $H(x)\psi=E\psi$ for all $x$.

Moreover, one has $\psi(j)=0$ for every $1\leq j \leq \ell$ such that the diagonal entry $x\in I\mapsto V_j(x)$ is not constant.

\label{prop:monotone_no_eigenvalue}
Let $f: \mathbb{T}\to \mathbb{R}$ be a monotone piecewise continuous sampling function with an interval $I$ such that $\operatorname*{ess\,inf}_{x\in I}f'(x)>0$ and $\ell_I(x)>1$ for every $x\in I$. Moreover, assume that no two discontinuity points of $f$ are on the same $\alpha$-orbit. Then there exists some interval $G\subset I$ such that the family
$$(H_{[1,\ell_G(x)-1]}(x))_{x\in \tilde{G}}$$ does not have a common eigenvalue, where $\tilde{G}\subset G$ is the set of continuity points of the map $x\mapsto H_{[1,\ell_G(x)-1]}(x)$.

\label{lemma:stripping}
Let $W_1$ and $W_2$ be two collections of words of the same alphabet such that for any $\tilde{w}\in W_2$ one either has $\tilde{w}\in W_1$ or there exist two words $v,w\in W_1$ such that $w=\tilde{w}lv$ or $w=vl\tilde{w}$ with some letter $l$.

If $W_2$ has no common Dirichlet eigenvalue then $W_1$ also has no common Dirichlet eigenvalue.

\label{prop:Lambda_functions}
    There exist functions $\Lambda_k:[0,1)\to\mathbb{R}$, $k=0,1,\ldots,n-1$, such that
    \begin{equation}
        \sigma\bigl(H_n(x)\bigr) = \Bigl\{\Lambda_0(x),\ \Lambda_1\bigl(\{x-\beta_{n-1}\}\bigr),\ \dots,\ \Lambda_{n-1}\bigl(\{x-\beta_1\}\bigr)\Bigr\}, \label{eq:spec-decomp}
    \end{equation}
    and
    \begin{equation}
			E_k(0) = \Lambda_k\bigl(\{-\beta_{n-k}\}\bigr),\qquad k=0,1,\dots,n-1. \label{eq:normalization}
    \end{equation}
		Furthermore, for $n\geq n_0$ and every $0\leq k\leq n-1$, $\Lambda_k$ is monotone on $[0,1)$.

\label{Assumption1}
There exists $\gamma>0$ and $n_0\in {\mathbb N}$ such that for $n\geq n_0$, the functions $(\Lambda_k)_{k=0}^{n-1}$ given by Proposition \ref{prop:Lambda_functions} satisfy
\begin{equation}\label{eq:gamma-monotone}
\Lambda_k(y)-\Lambda_k(x) \ge \gamma\,(y-x)\quad\text{for all }0\le x\le y<1.
\end{equation}

\label{Assumption2}

For every $x\in[0,1)$ and every $k=1,\dots,n-1$,
\begin{equation}\label{eq:interlace}
E_k(x) \ge E_{k-1}(x-0).
\end{equation}

Following \cite{Kach}, for $E_1<E_2$ we have
\begin{equation}
			\frac{1}{n}\overline N_n(E_2)-\frac{1}{n}\overline N_n(E_1)=\frac{1}{n}\sum_{i=0}^{n-1}\int_0^1\chi_{(E_1,E_2]}\left[\Lambda_i(x)\right]dx\leq\gamma^{-1}(E_2-E_1),
\end{equation}    
		where the inequality follows from Assumption \ref{Assumption1}. Taking the limit for $n\to \infty$ completes the proof.

\label{JK:3.4}
    For every $q\in\mathbb{N}$ a continued fraction denominator, $E\in\mathbb{R}$ and $x,y\in[0,1)$,
    \begin{equation}\label{eq:Nqx-Nqy}
        \left|N_{q}(x,E)-N_{q}(y,E)\right|\leq 2n_0+22.
    \end{equation}
    As a consequence, we have
     \begin{equation}\label{eq:discrepancy_dos}
        \left|\frac{1}{q}N_{q}(x,E)-N(E)\right|<\frac{4n_0+50}{q}.
    \end{equation}

\label{lemma:eigenvalue_monotonicity_tech1}
If $\{q\alpha\}>\frac{1}{2}$ one has
\begin{equation}\label{eq:small_qa}
    N_{q}(x,E) - 6-n_0 \leq N_{q}(x+m\alpha,E) \leq N_{q}(x+ q\alpha,E) + 6+n_0
\end{equation}

and if $\{q\alpha\}<\frac{1}{2}$, one has
\begin{equation}\label{eq:large_qa}
    N_{q}(x+q\alpha,E) - 6-n_0 \leq N_{q}(x+m\alpha,E) \leq N_{q}(x,E) + 6+n_0
\end{equation}
for all $m \in 0,...,q-1$.

Assume first $\{q\alpha\}<\frac{1}{2}$, in which case one actually has $\{q\alpha\}<\frac{1}{q}$. Fix $0\leq m\leq q-1$. There exist perturbations $R_1$, $R_2$ of rank at most $2$ and a unitary operator $U$ (a cyclic shift) such that
\begin{align*}
H_q(x+m\alpha) &= H_{q-m}(x+m\alpha)\oplus H_{m}(x+q\alpha) + R_1 \\
H_{q-m}(x+m\alpha)\oplus H_{m}(x)&= U H_{q}(x)U^* +R_2.
\end{align*}
		If $m\geq n_0$ then the eigenvalue counting function $y\mapsto N_{m}(y,E)$ is non-increasing except for at jump points $\beta_j$ which are on the arc $[x, x+q\alpha]$ where it can jump by $1$ each. Since $q$ is a continued fraction denominator the distance between consecutive jump points satisfies $|\beta_{j+1}-\beta_{j}|>\frac{1}{2q}$ (see e.g. \cite[Proposition 2.1]{JK2}), hence there can be at most two points on the arc. We then conclude
\begin{align*}
N_q(x+m\alpha,E)&\leq N_{q-m}(x+m\alpha,E) + N_{m}(x+q\alpha,E) +2 \\
&\leq N_{q-m}(x+m\alpha,E) + N_{m}(x,E) +4 \\
&\leq N_{q}(x,E) + 6
\end{align*}
If $m<n_0$ we can bound trivially $$N_{m}(x+q\alpha,E)\leq N_{m}(x,E) + n_0$$
hence we can use the bound $N_{m}(x+q\alpha,E)\leq N_{m}(x,E) + 6+n_0$ in either case. Replacing $x$ by $x+m\alpha$ and $m$ by $q-m$ gives the inequality in the other direction.

\label{cor:JK-3.5}
    Let $m\in\mathbb{N}$. Suppose that $m=sq+r$ with $q,m\geq n_0$. Then for every $x,y\in\mathbb{R}$,
    \begin{equation}\label{eq:JK-3.7}
        \left|N_m(x,E)-sN_q(y,E)\right|\leq (2n_0+22)s+4(s+|r|)
    \end{equation}
    and as a consequence
    \begin{equation}\label{eq:JK-3.8}
        \left|N_m(x,E)-N_m(y,E)\right|\leq (4n_0+44)s+8(s+|r|).
    \end{equation}

Any Schr\"{o}dinger operator acting on $\ell^2(I)$, where $I$ is some integer interval, can be disconnected along an edge using a perturbation of rank at most $2$. Hence, by the structure of $H_m(x)$, we get that
    \begin{equation}
    \label{eq:block_decomposition} 
        H_m(x)=H_q(x)\oplus H_q(x+q\alpha)\oplus\ldots\oplus H_q(x+(s-1)q\alpha)+P
    \end{equation}
    where $\operatorname{rank}P\leq 2s+|r|$ (if $r<0$ this is to be understood as an equality after padding $H_m(x)$ with $r$ zero diagonal entries). Indeed, using rank $2$ perturbations, we disconnect along the edges $(kq-1,kq)$ for $1\leq k\leq s$, and subtract the remaining part $H_r(x+sq\alpha)$ which is of rank at most $r$. Now we apply Proposition \ref{JK:3.4} for each direct summand and get the result. \eqref{eq:JK-3.8} now follows from the triangle inequality.

With the same notation, we have that
\begin{equation}\label{eq:JK-3.12}
    \left|\frac{1}{m}N_m(x,E)-N(E)\right|\leq\frac{8|r|}{sq}+\frac{8n_0+200}{q}.
\end{equation}
    As a consequence, $\frac{1}{n}N_n(x,E)$ converges to $N(E)$ uniformly in $x$.

A direct consequence of Corollary \ref{cor:JK-3.5} and the triangle inequality is that for $m=sq+r$ we have
\begin{align}
\left|\frac{1}{m}N_m(x,E)-\frac{1}{q}N_q(x,E)\right|
&\leq\left| \frac{1}{m}N_m(x,E)-\frac{s}{m}N_q(x,E)\right|
    +\left|\frac{s}{m}N_q(x,E)-\frac{1}{q}N_q(x,E)\right| \notag\\
&\leq\left(\frac{(2n_0+26)s}{m}+\frac{4|r|}{m}\right)
    +\left|\frac{s}{m}-\frac{1}{q}\right|N_q(x,E) \notag\\
&\leq\frac{4n_0+52}{q}+\frac{8|r|}{sq}.
\end{align}
By the triangle inequality, for $m_1=s_1q+r_1$ and $m_2=s_2q+r_2$ we now have
    \begin{equation}
        \left|\frac{1}{m_1}N_{m_1}(x,E)-\frac{1}{m_2}N_{m_2}(y,E)\right|\leq \frac{8|r_1|}{s_1q}+\frac{8|r_2|}{s_2q}+\frac{8n_0+200}{q}.
    \end{equation}
    Taking $m=sq+r$, $m'=s'q$ for some $m'\in\mathbb{N}$, we obtain
    \begin{equation}
        \left|\frac{1}{m}N_{m}(x,E)-\frac{1}{m'}N_{m'}(y,E)\right|\leq \frac{8|r|}{sq}+\frac{8n_0+200}{q}.
    \end{equation}
    Integrating this inequality over $y$ and taking $m'$ to $\infty$ yields \eqref{eq:JK-3.12}, which immediately implies uniform convergence.

\label{cor:JK-3.7}
    Let $g:\mathbb{R}\to\mathbb{R}$ be a function of bounded variation. Then for every $x\in\mathbb{R}$,
    \begin{equation}
        \left|\int_\mathbb{R}g(E')dN(E')-\frac{1}{n}\sum\limits_{j=0}^{n-1}g(E_j(x))\right|\leq\|g\|_{\text{BV}}\left(\frac{8|r|}{sq}+\frac{8n_0+200}{q}\right).
    \end{equation}

The discrepancy of a sequence $z_1,\ldots,z_n\in[0,1]$ is defined by
    \begin{equation*}
        D_n^*(z_1,\ldots,z_n)=\sup\limits_{t\in(0,1]}\left|\frac{\#\left\{k:z_k\in[0,t)\right\}}{n}-t\right|.
    \end{equation*}

\label{prop:Koksma}
    Let \mbox{$f:[0,1]\to\mathbb{R}$} be a function of bounded variation and let $z_1,\ldots,z_n$ be a sequence of points in $[0,1]$. Then
    \begin{equation}
        \left|\int_0^1f(t)\,dt-\frac{1}{n}\sum\limits_{i=1}^n f(z_i)\right|\leq\|f\|_{\text{BV}}\cdot D_n^*(z_1,\ldots,z_n).
    \end{equation}

\label{lemma:lyapunov_uniformity}
    We have the following:
    \begin{equation}
        L(E)=(1+o(1))\log |E|,\qquad E\to\pm\infty,
    \end{equation}
    and 
    \begin{equation}
        \bigl|L(E;[B_-,B_+^{\log(2+\lvert E\rvert)}]) - L(E)\bigr|
\leq o(1)(1+L(E)),
\qquad \text{as } B_- \to +0,\; B_+ \to +\infty,
    \end{equation}
    where $o(1)$ is uniform in $E$.

For any $n \in \mathbb{N}$ we have
\begin{equation}
\label{eq:JK-4.8}
    1\geq \left|P_n^{\text{small}}(x,E)\right|\geq\prod\limits_{k:\gamma\|x-z_k(E)\|<B_-}\gamma\|x-z_k(E)\|.
\end{equation}
If $n=sq+r$ for $q$ a denominator of the continued fraction expansion then the number of factors on the right-hand side can be bounded by
    \begin{equation}
        \#\left\{0\leq k\leq n-1:\gamma\|x-z_k(E)\|<B_-\right\}\leq\frac{4sq B_-}{\gamma}+(8n_0+100)(s+|r|).
    \end{equation}

\label{prop:num_of_large_entries}
For large enough $B_+$ we have
\begin{equation}\label{eq:JK_4.11}
    \#\Bigl\{k:\, \lvert f(x+k\alpha)-E\rvert > B_+^{\log(2+|E|)} - 2\Bigr\}\leq 8n_0(s+|r|)+n\frac{n_0 C(f)}{\log B_+},
\end{equation}
where
\[
    C(f) := \sup_E \frac{1}{\log(2+\lvert E\rvert)}
\int_0^1 \log\bigl(\lvert f(x)-E\rvert + 6\bigr)\,dx < \infty .
\]

\label{prop:mid_factor_prop}
For $n=sq+r$ we have
    \begin{equation}
    \begin{split}
        \bigg|
        \frac{1}{n}\log |P^{\mathrm{mid}}_n(x,E)|
        -&\int_{\mathbb{R}}\log\lvert E-E'\rvert_{[B_-,B_+^{\log(2+|E|)}]}dN(E')
        \bigg| \\
        &        \le 2000\,n_0\,\frac{s+\lvert r\rvert}{n}(\log(2+|E|)\log B_+-\log B_-).
    \end{split}
    \end{equation}

\label{lemma:JK-6.1}
Let $p(x)=x^n+a_{n-1}x^{n-1}+\cdots+a_0$ be a polynomial with real coefficients, and let
$x_0,\dots,x_n\in\mathbb{R}$ satisfy $|x_i-x_j|\geq d$ for $i\ne j$.
Then, at least one of the above points satisfies
\begin{equation}\tag{6.3}
|p(x_j)| \geq \left(\frac{d}{2}\right)^n n!.
\end{equation}

\label{lemma:JK-6.2}
Let $I\subset\mathbb{R}$ be an interval with $|I|<(10\gamma)^{-1}$, and let
$x_0,\dots,x_l\in I$ satisfy $|x_i-x_j|\geq d>0$ for $i\ne j$.
Assume that $I$ contains at most $t\leq l$ intersection points \eqref{eq:intersection_pts} for $P_n$,
and all other intersection points $z$ of $P_n$ satisfy
\begin{equation}\tag{6.4}
\mathrm{dist}(z,I)\geq \gamma^{-1}B_- .
\end{equation}
Then, for at least one $j\in[0,l]$, we have
\begin{equation}\tag{6.5}
\bigl|P_n^{\text{small}}(x_j)\bigr|\geq \gamma^{t}\left(\frac{d}{2}\right)^{t}t!.
\end{equation}
